      ('Квадро Вулкан', '10х20 см', 12000, 50),
      ('Квадро Чіназес', '10х20 см', 11000, 50),
      ('Квадро Палермо', '10х20 см', 12500, 50),
      ('Квадро Паляниця', '10х20 см', 13000, 50),
      ('Квадро Карбонара', '10х20 см', 12000, 50),
      ('Квадро Прошуто Ананас', '10х20 см', 15500, 50),
      ('Квадро Чізбургер', '10х20 см', 13500, 50),
      ('Квадро з Лисичками', '10х20 см', 13500, 50),
      ('Квадро Бос BBQ', '10х20 см', 16000, 50)
    ) AS t(product, size, price, qty)
  LOOP
    SELECT id INTO v_prod FROM pos_products WHERE store_id = v_store AND name = r.product;
    INSERT INTO pos_variants (store_id, product_id, attributes, label, unit, price_cents, cost_cents)
    VALUES (
      v_store, v_prod,
      CASE WHEN r.size IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('size', r.size) END,
      COALESCE(r.size, ''),
      'шт', r.price, 0
    )
    RETURNING id INTO v_variant;
    INSERT INTO pos_stock (variant_id, store_id, quantity) VALUES (v_variant, v_store, r.qty);
    IF r.qty > 0 THEN
      INSERT INTO pos_stock_movements (store_id, variant_id, delta, reason, note)
      VALUES (v_store, v_variant, r.qty, 'seed', 'Initial stock');
    END IF;
  END LOOP;

  -- ── Pizza questions ─────────────────────────────────────────────────────
  -- One crust and one sauce, both optional, as on the site. The crust costs
  -- more on the 50 см pizza: `label_deltas` (066) holds that size's price.
  FOR r IN
    SELECT * FROM (VALUES
      ('Бортики', 0, 1, 10),
      ('Соус', 0, 1, 20)
    ) AS t(name, min_sel, max_sel, ord)
  LOOP
    INSERT INTO pos_modifier_groups (store_id, name, min_select, max_select, sort_order)
    VALUES (v_store, r.name, r.min_sel, r.max_sel, r.ord);
  END LOOP;

  FOR c IN
    SELECT * FROM (VALUES
      ('Бортики', 'Філадельфія', 8000, '[{"label":"50 см","price_delta_cents":15000}]', 0),
      ('Бортики', 'Моцарелла', 5000, '[{"label":"50 см","price_delta_cents":8000}]', 1),
      ('Бортики', 'Кунжутний', 1000, '[{"label":"50 см","price_delta_cents":1500}]', 2),
      ('Соус', 'Бургер', 3000, '[]', 0),
      ('Соус', 'Гострий', 3000, '[]', 1),
      ('Соус', 'Спайс', 3000, '[]', 2),
      ('Соус', 'Часникова олія', 3000, '[]', 3)
    ) AS t(grp, answer, delta, label_deltas, ord)
  LOOP
    SELECT id INTO v_group FROM pos_modifier_groups WHERE store_id = v_store AND name = c.grp;
    INSERT INTO pos_modifiers (store_id, group_id, name, price_delta_cents, label_deltas, sort_order)
    VALUES (v_store, v_group, c.answer, c.delta, c.label_deltas::jsonb, c.ord);
  END LOOP;

  INSERT INTO pos_product_modifier_groups (store_id, product_id, group_id, sort_order)
  SELECT v_store, p.id, g.id, x.ord
  FROM (VALUES
      ('Double Meet', 'Бортики', 0),
      ('Double Meet', 'Соус', 1),
      ('Double Fish', 'Бортики', 0),
      ('Double Fish', 'Соус', 1),
      ('4 сира', 'Бортики', 0),
      ('4 сира', 'Соус', 1),
      ('Веган', 'Бортики', 0),
      ('Веган', 'Соус', 1),
      ('Пепероні', 'Бортики', 0),
      ('Пепероні', 'Соус', 1),
      ('Філадельфія', 'Бортики', 0),
      ('Філадельфія', 'Соус', 1),
      ('Маринара', 'Бортики', 0),
      ('Маринара', 'Соус', 1),
      ('Дитяча', 'Бортики', 0),
      ('Дитяча', 'Соус', 1),
      ('Fire', 'Бортики', 0),
      ('Fire', 'Соус', 1),
      ('Double Chicken', 'Бортики', 0),
      ('Double Chicken', 'Соус', 1),
      ('Жульєн', 'Бортики', 0),
      ('Жульєн', 'Соус', 1),
      ('Double Cheese', 'Бортики', 0),
      ('Double Cheese', 'Соус', 1),
      ('М''ясна', 'Бортики', 0),
      ('М''ясна', 'Соус', 1),
      ('Дольче', 'Бортики', 0),
      ('Дольче', 'Соус', 1),
      ('Чотири сезона', 'Бортики', 0),
      ('Чотири сезона', 'Соус', 1),
      ('Алегрі', 'Бортики', 0),
      ('Алегрі', 'Соус', 1),
      ('Гавайська', 'Бортики', 0),
      ('Гавайська', 'Соус', 1),
      ('Маргарита', 'Бортики', 0),
      ('Маргарита', 'Соус', 1),
      ('Капрічоза', 'Бортики', 0),
      ('Капрічоза', 'Соус', 1),
      ('Прошутто', 'Бортики', 0),
      ('Прошутто', 'Соус', 1),
      ('Прошутто крудо', 'Бортики', 0),
      ('Прошутто крудо', 'Соус', 1),
      ('Креветка Дор-Блю', 'Бортики', 0),
      ('Креветка Дор-Блю', 'Соус', 1),
      ('Sun City', 'Бортики', 0),
      ('Sun City', 'Соус', 1),
      ('Салямі', 'Бортики', 0),
      ('Салямі', 'Соус', 1),
      ('Тунець', 'Бортики', 0),
      ('Тунець', 'Соус', 1),
      ('Вулкан', 'Бортики', 0),
      ('Вулкан', 'Соус', 1),
      ('Чіназес', 'Бортики', 0),
      ('Чіназес', 'Соус', 1),
      ('Палермо', 'Бортики', 0),
      ('Палермо', 'Соус', 1),
      ('Паляниця', 'Бортики', 0),
      ('Паляниця', 'Соус', 1),
      ('Карбонара', 'Бортики', 0),
      ('Карбонара', 'Соус', 1),
      ('Прошуто Ананас', 'Бортики', 0),
      ('Прошуто Ананас', 'Соус', 1),
      ('Чізбургер', 'Бортики', 0),
      ('Чізбургер', 'Соус', 1),
      ('Піца з лисичками', 'Бортики', 0),
      ('Піца з лисичками', 'Соус', 1),
      ('Бос BBQ', 'Бортики', 0),
      ('Бос BBQ', 'Соус', 1),
      ('BBQ Gold', 'Бортики', 0),
      ('BBQ Gold', 'Соус', 1)
  ) AS x(product, grp, ord)
  JOIN pos_products p ON p.store_id = v_store AND p.name = x.product
  JOIN pos_modifier_groups g ON g.store_id = v_store AND g.name = x.grp;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 70 THEN
    RAISE EXCEPTION 'demo-suncity: % of 70 pizza questions attached', v_rows;
  END IF;

  -- ── The expanded recipes ────────────────────────────────────────────────
  -- 045 already ran this boot, before this store existed: `recomputeFlat`'s
  -- SQL for this store only (048 does the same).
  DELETE FROM pos_product_components_flat WHERE store_id = v_store;
  INSERT INTO pos_product_components_flat (store_id, variant_id, leaf_variant_id, quantity_per_unit)
  WITH RECURSIVE walk AS (
    SELECT pc.store_id, pc.variant_id AS root_id, pc.component_variant_id AS node_id,
           pc.quantity::bigint AS qty, 1 AS depth
    FROM pos_product_components pc
    WHERE pc.store_id = v_store
    UNION ALL
    SELECT w.store_id, w.root_id, pc.component_variant_id, w.qty * pc.quantity, w.depth + 1
    FROM walk w
    JOIN pos_variants nv ON nv.id = w.node_id
    JOIN pos_products np ON np.id = nv.product_id
    JOIN pos_product_components pc ON pc.variant_id = w.node_id AND pc.store_id = w.store_id
    WHERE np.kind = 'composite' AND np.stock_mode = 'derived' AND w.depth < 8
  )
  SELECT w.store_id, w.root_id, w.node_id, SUM(w.qty)::int
  FROM walk w
  JOIN pos_variants lv ON lv.id = w.node_id
  JOIN pos_products lp ON lp.id = lv.product_id
  WHERE NOT (lp.kind = 'composite' AND lp.stock_mode = 'derived')
  GROUP BY w.store_id, w.root_id, w.node_id;

  -- ── The guest's menu ────────────────────────────────────────────────────
  -- Published at /m/demo-suncity-menu with the place's own header. Only while
  -- empty, like 056/059: whatever the owner (or a visitor with the demo's
  -- credentials) set afterwards stays. No guest ordering — there are no tables.
  UPDATE pos_stores
     SET public_menu_token = 'demo-suncity-menu', public_menu_enabled = TRUE
   WHERE id = v_store AND public_menu_token IS NULL;

  UPDATE pos_stores
     SET public_logo_url = '/demo-suncity/logo.png',
         public_address = 'вул. 10 ОГШБ 52а, м. Малин',
         public_phone = '+380684868060',
         public_hours = '{"1":{"open":"11:00","close":"22:30"},"2":{"open":"11:00","close":"22:30"},"3":{"open":"11:00","close":"22:30"},"4":{"open":"11:00","close":"22:30"},"5":{"open":"11:00","close":"22:30"},"6":{"open":"11:00","close":"22:30"},"7":{"open":"11:00","close":"22:30"}}'::jsonb
   WHERE id = v_store
     AND public_logo_url IS NULL AND public_address IS NULL
     AND public_phone IS NULL AND public_hours IS NULL;

  INSERT INTO pos_demo_seed (slug, version) VALUES ('demo-suncity', v_version)
  ON CONFLICT (slug) DO UPDATE SET version = EXCLUDED.version, applied_at = NOW();

  RAISE NOTICE 'demo-suncity store ready at version % (id %)', v_version, v_store;
END $$;
